/* Serve a page's Markdown copy (index.md, generated by mkdocs-llmstxt) when a
 * client asks for text/markdown. Requests without that Accept header never
 * run this function, so browsers keep getting the static HTML. */
export default async (request) => {
  const url = new URL(request.url);
  if (!url.pathname.endsWith("/")) return;

  // Netlify's custom headers do not apply to edge function responses, so read
  // the static copy and set the Markdown content type here.
  const markdown = await fetch(new URL(url.pathname + "index.md", url));
  if (!markdown.ok) return; // No copy (e.g. blog archives): fall back to HTML.

  const headers = new Headers({
    "Content-Type": "text/markdown; charset=utf-8",
    "Vary": "Accept",
  });
  for (const name of ["Cache-Control", "ETag"]) {
    if (markdown.headers.has(name)) headers.set(name, markdown.headers.get(name));
  }
  return new Response(markdown.body, { headers });
};

export const config = {
  path: "/*",
  header: { accept: "text/markdown" },
  onError: "bypass", // On failure, serve the page as usual instead of an error page.
};
